<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>WastedToken Mint — Physical Challenge Coins</title>
<style>
:root{--ink:#eee8dc;--muted:#a79f91;--bg:#10110f;--panel:#191b18;--line:#34362f;--copper:#bd6c39;--lime:#d4f264}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:Georgia,"Times New Roman",serif}
body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.08;background-image:radial-gradient(#fff 1px,transparent 1px);background-size:5px 5px;mix-blend-mode:screen}
nav{height:76px;padding:0 6vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);position:relative;z-index:2;background:#10110fee}
.logo{font:700 15px/1 Arial,sans-serif;letter-spacing:.2em;text-transform:uppercase}.logo i{font-style:normal;color:var(--lime)}
nav a{color:var(--muted);text-decoration:none;font:12px Arial,sans-serif;letter-spacing:.13em;text-transform:uppercase;margin-left:28px}
nav a:hover{color:var(--lime)}
.hero{min-height:calc(100vh - 76px);display:grid;grid-template-columns:1fr 1.08fr;align-items:center;gap:2vw;padding:5vh 6vw 8vh;max-width:1500px;margin:auto}
.kicker{color:var(--lime);font:11px Arial,sans-serif;letter-spacing:.28em;text-transform:uppercase;margin-bottom:25px}
h1{font-size:clamp(52px,7vw,108px);line-height:.88;letter-spacing:-.065em;margin:0 0 30px;font-weight:700;max-width:620px}
h1 span{color:var(--copper)}
.lede{font-size:20px;line-height:1.5;color:#c5beb1;max-width:480px;margin:0 0 34px}
.cta{display:inline-block;padding:16px 22px;background:var(--lime);color:#141510;text-decoration:none;font:700 11px Arial,sans-serif;letter-spacing:.16em;text-transform:uppercase}
.hero-art{height:min(690px,72vw);min-height:410px;display:flex;align-items:center;justify-content:center;position:relative}
#coin-hero{width:100%;height:100%;display:block}
.stamp{position:absolute;bottom:5%;right:5%;font:10px Arial,sans-serif;color:#68695f;letter-spacing:.16em;text-transform:uppercase;writing-mode:vertical-rl}
section{padding:110px 6vw;max-width:1500px;margin:auto}.section-head{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid var(--line);padding-bottom:24px;margin-bottom:45px}
h2{font-size:clamp(38px,5vw,68px);letter-spacing:-.05em;line-height:.9;margin:0}.section-note{color:var(--muted);font:12px Arial,sans-serif;letter-spacing:.12em;text-transform:uppercase}
.about{display:grid;grid-template-columns:1fr 1fr;gap:10vw}.about p{font-size:clamp(23px,3vw,40px);line-height:1.16;margin:0;letter-spacing:-.03em}.about aside{border-left:1px solid var(--copper);padding-left:26px;color:var(--muted);font:15px/1.7 Arial,sans-serif;max-width:430px}
.collection{background:#151713;max-width:none;padding-left:6vw;padding-right:6vw}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.edition{background:var(--panel);border:1px solid var(--line);min-width:0;position:relative;overflow:hidden}.edition-canvas{width:100%;height:260px;display:block;background:#171914}.edition-info{padding:22px 20px 20px}.edition-name{font-size:28px;margin:0 0 8px}.edition-meta{font:10px Arial,sans-serif;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);min-height:28px}.price{font:16px Arial,sans-serif;color:var(--lime);margin:20px 0 17px}.buy{border:1px solid var(--lime);background:transparent;color:var(--lime);padding:12px 15px;width:100%;font:700 10px Arial,sans-serif;letter-spacing:.14em;text-transform:uppercase;cursor:pointer}.buy:hover{background:var(--lime);color:#141510}.sold{color:#e37a52}.coming{color:#aaa79a}
footer{padding:32px 6vw;border-top:1px solid var(--line);color:#66695f;font:10px Arial,sans-serif;letter-spacing:.16em;text-transform:uppercase;display:flex;justify-content:space-between}
@media(max-width:850px){.hero{grid-template-columns:1fr;padding-top:70px}.hero-art{order:-1;height:75vw;min-height:300px}.about{grid-template-columns:1fr;gap:35px}.grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:500px){nav a{display:none}.grid{grid-template-columns:1fr}.edition-canvas{height:280px}section{padding-top:75px;padding-bottom:75px}}
</style>
</head>
<body>
<nav><div class="logo">Wasted<span>Token</span> <i>Mint</i></div><div><a href="#about">The mint</a><a href="#collection">Editions</a></div></nav>

<main>
<section class="hero">
  <div class="hero-copy">
    <div class="kicker">Series 01 / The improbable reserve</div>
    <h1>Make the<br><span>moment</span><br>metal.</h1>
    <p class="lede">Physical challenge coins for improbable wins, questionable decisions, and the stories that get better every time they’re told.</p>
    <a class="cta" href="#collection">Collect the first run</a>
  </div>
  <div class="hero-art"><canvas id="coin-hero"></canvas><div class="stamp">Strike hard · carry often</div></div>
</section>

<section id="about">
  <div class="section-head"><h2>The mint</h2><div class="section-note">Small batch / heavy metal</div></div>
  <div class="about">
    <p>WastedToken Mint turns tiny victories into objects with actual gravity.</p>
    <aside>Every coin is conceived like a badge from an alternate history, then struck, finished, and numbered in limited runs. No digital points. No vapor. Just a dense little reminder that you were there when it happened.</aside>
  </div>
</section>

<section id="collection" class="collection">
  <div class="section-head"><h2>First editions</h2><div class="section-note">01—04 / Choose your alloy</div></div>
  <div class="grid">
    <div class="edition" data-edition="bronze" data-state="available">
      <canvas class="edition-canvas"></canvas><div class="edition-info"><h3 class="edition-name">Bronze</h3><div class="edition-meta">Warm patina · 500 struck</div><div class="price">$48.00</div><button class="buy">Add to cart</button></div>
    </div>
    <div class="edition" data-edition="silver" data-state="available">
      <canvas class="edition-canvas"></canvas><div class="edition-info"><h3 class="edition-name">Silver</h3><div class="edition-meta">Mirror finish · 250 struck</div><div class="price">$72.00</div><button class="buy">Add to cart</button></div>
    </div>
    <div class="edition" data-edition="gold" data-state="sold-out">
      <canvas class="edition-canvas"></canvas><div class="edition-info"><h3 class="edition-name">Gold</h3><div class="edition-meta sold">SOLD OUT · 25 struck</div><div class="price">$180.00</div></div>
    </div>
    <div class="edition" data-edition="black" data-state="coming-soon">
      <canvas class="edition-canvas"></canvas><div class="edition-info"><h3 class="edition-name">Black</h3><div class="edition-meta coming">MINTING NEXT SEASON · AUTUMN 2026</div><div class="price">Join the ledger</div></div>
    </div>
  </div>
</section>
</main>
<footer><span>WastedToken Mint © 2026</span><span>Made for the long story</span></footer>

<script>
(function(){
const hero=document.getElementById("coin-hero"), hc=hero.getContext("2d"), TAU=Math.PI*2;
let paused=false, raf=0, current=0;
const palettes={
 hero:["#b46b3b","#e2a06a","#6d321d","#f5c18a"],
 bronze:["#9d5128","#e3a16a","#5a2617","#ffc38e"],
 silver:["#89939b","#f5fbf7","#343c42","#ffffff"],
 gold:["#b98220","#ffe095","#68410b","#fff0a7"],
 black:["#293039","#aeb4b7","#090d12","#e5f2ed"]
};
function size(c,scale){let r=c.getBoundingClientRect(),d=Math.min(2,devicePixelRatio||1);c.width=Math.max(1,r.width*d);c.height=Math.max(1,r.height*d);let x=c.getContext("2d");x.setTransform(d,0,0,d,0,0);return [r.width,r.height,x]}
function ellipse(ctx,x,y,rx,ry,fill){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,TAU);ctx.fillStyle=fill;ctx.fill()}
function coin(ctx,w,h,t,kind){
 ctx.clearRect(0,0,w,h);ctx.fillStyle=kind==="hero"?"#10120f":"#171914";ctx.fillRect(0,0,w,h);
 let p=palettes[kind], cx=w/2, cy=h/2, R=Math.min(w,h)*(kind==="hero"?.285:.31);
 let yaw=TAU*t, pitch=TAU*t*.82, side=Math.abs(Math.cos(yaw)), faceFront=Math.cos(yaw)>=0;
 let sy=.82+.18*Math.abs(Math.cos(pitch)), rx=R*(.20+.80*side), ry=R*sy, edge=Math.max(8,R*.075);
 ctx.save();ctx.shadowColor="rgba(0,0,0,.7)";ctx.shadowBlur=28;ctx.shadowOffsetY=16;
 ellipse(ctx,cx,cy+edge*.42,rx+edge,ry+edge*.72,p[2]);ctx.restore();
 let edgeGrad=ctx.createLinearGradient(cx-rx,cy,cx+rx,cy);edgeGrad.addColorStop(0,p[2]);edgeGrad.addColorStop(.5,p[1]);edgeGrad.addColorStop(1,p[2]);
 ellipse(ctx,cx,cy,rx+edge,ry+edge*.7,edgeGrad);
 ctx.save();ctx.globalAlpha=.65;ctx.strokeStyle=p[1];ctx.lineWidth=1;
 for(let i=-10;i<=10;i++)if(side<.72||i%2===0){ctx.beginPath();ctx.moveTo(cx+rx+i*2,cy-ry*.7);ctx.lineTo(cx+rx+i*2-3,cy+ry*.7);ctx.stroke()}
 ctx.restore();
 let grad=ctx.createRadialGradient(cx-rx*.38,cy-ry*.45,R*.1,cx,cy,R*1.2);grad.addColorStop(0,p[1]);grad.addColorStop(.42,p[0]);grad.addColorStop(1,p[2]);
 ellipse(ctx,cx,cy,Math.max(2,rx),Math.max(2,ry),grad);
 ctx.save();ctx.beginPath();ctx.ellipse(cx,cy,rx*.92,ry*.9,0,0,TAU);ctx.clip();
 let light=(t*1.7)%1, lx=cx-rx+light*rx*2;
 let shine=ctx.createLinearGradient(lx-rx*.24,0,lx+rx*.24,0);shine.addColorStop(0,"rgba(255,255,255,0)");shine.addColorStop(.5,"rgba(255,255,255,.42)");shine.addColorStop(1,"rgba(255,255,255,0)");
 ctx.fillStyle=shine;ctx.fillRect(cx-rx,cy-ry,cx+rx,ry*2);
 ctx.restore();
 ctx.save();ctx.strokeStyle="rgba(255,238,187,.68)";ctx.lineWidth=Math.max(1,R*.018);ctx.beginPath();ctx.ellipse(cx,cy,rx*.88,ry*.86,0,0,TAU);ctx.stroke();ctx.restore();
 if(rx>R*.32){
   ctx.save();ctx.translate(cx,cy);ctx.scale(1,sy);ctx.rotate(pitch*.12);
   ctx.strokeStyle="rgba(35,22,13,.75)";ctx.lineWidth=R*.025;ctx.beginPath();ctx.arc(0,0,R*.60,0,TAU);ctx.stroke();
   ctx.strokeStyle="rgba(255,217,151,.5)";ctx.lineWidth=R*.012;ctx.beginPath();ctx.arc(0,0,R*.54,0,TAU);ctx.stroke();
   ctx.fillStyle=faceFront?"rgba(34,25,17,.82)":"rgba(20,25,27,.9)";ctx.textAlign="center";ctx.textBaseline="middle";
   if(faceFront){
     ctx.font="bold "+R*.26+"px Arial";ctx.fillText("W",0,-R*.05);
     ctx.font="bold "+R*.085+"px Arial";ctx.letterSpacing="3px";ctx.fillText("WASTEDTOKEN",0,R*.28);
     ctx.font=R*.055+"px Arial";ctx.fillText("MINT · EST. 2026",0,-R*.29);
     ctx.strokeStyle="rgba(255,220,161,.55)";ctx.lineWidth=R*.012;ctx.beginPath();ctx.moveTo(-R*.38,R*.2);ctx.lineTo(R*.38,R*.2);ctx.stroke();
   }else{
     ctx.font="bold "+R*.19+"px Arial";ctx.fillText("10,000",0,-R*.08);
     ctx.font="bold "+R*.065+"px Arial";ctx.fillText("TOKENS",0,R*.17);
     ctx.font=R*.045+"px Arial";ctx.fillText("ONE GOOD STORY",0,R*.35);
   }
   ctx.restore();
 }
}
function render(t){current=((t%1)+1)%1;let [w,h,x]=size(hero);coin(x,w,h,current,"hero");document.querySelectorAll(".edition").forEach(el=>{let c=el.querySelector("canvas"),q=size(c);coin(q[2],q[0],q[1],current,el.dataset.edition)})}
function loop(ms){if(!paused){render((ms%7200)/7200);raf=requestAnimationFrame(loop)}}
window.demo={canvas:hero,setTime(t){render(t)},pause(){paused=true;cancelAnimationFrame(raf)}};
render(0);raf=requestAnimationFrame(loop);window.addEventListener("resize",()=>render(current));
})();
</script>
</body>
</html>
